{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.meta_category_total_spends as with category_map as ( select * from values (\'OVERSHIRT\', \'OVERSHIRTS\') as t(raw_key, clean_key) ), scorecard_daily as ( select cast(s.date as date) as spend_date, coalesce(m.clean_key, upper(trim(coalesce(s.nom_category,\'UNCATEGORIZED\')))) as category_key, sum(coalesce(s.spend,0)) as scorecard_spend from snitch_db.maplemonk.meta_scorecard s left join category_map m on m.raw_key = upper(trim(coalesce(s.nom_category,\'UNCATEGORIZED\'))) where s.date is not null group by 1,2 ), catalogue_daily as ( select cast(c.spend_date as date) as spend_date, coalesce(m.clean_key, upper(trim(coalesce(c.category,\'UNCATEGORIZED\')))) as category_key, sum(coalesce(c.amount_spent_inr,0)) as catalogue_spend from snitch_db.maplemonk.v_meta_product_spends_catalogue c left join category_map m on m.raw_key = upper(trim(coalesce(c.category,\'UNCATEGORIZED\'))) where c.spend_date is not null group by 1,2 ), sales_daily as ( select cast(h.date as date) as sale_date, coalesce(m.clean_key, upper(trim(h.category))) as category_key, sum(coalesce(h.gross_sales,0)) as sales from snitch_db.maplemonk.horizontal_sales_categories h left join category_map m on m.raw_key = upper(trim(h.category)) where h.type = \'Shopify\' and h.date is not null and h.category is not null group by 1,2 ), daily as ( select coalesce(s.spend_date, c.spend_date) as spend_date, coalesce(s.category_key, c.category_key) as category_key, coalesce(s.scorecard_spend,0) as scorecard_spend, coalesce(c.catalogue_spend,0) as catalogue_spend, coalesce(s.scorecard_spend,0) + coalesce(c.catalogue_spend,0) as total_spend from scorecard_daily s full outer join catalogue_daily c on s.spend_date = c.spend_date and s.category_key = c.category_key ), spine as ( select d.spend_date, c.category_key from (select distinct spend_date from daily) d cross join (select distinct category_key from daily) c ), spends as ( select sp.spend_date as date, sp.category_key as nom_category, coalesce(d.scorecard_spend,0) as scorecard_spend, coalesce(d.catalogue_spend,0) as catalogue_spend, coalesce(d.total_spend,0) as total_spend from spine sp left join daily d on d.spend_date = sp.spend_date and d.category_key = sp.category_key ) select s.date, s.nom_category, s.scorecard_spend, s.catalogue_spend, s.total_spend, sl.sales, round(sl.sales / nullif(s.total_spend, 0), 2) as roas, round(sl.sales / nullif(s.scorecard_spend, 0), 2) as roas_scorecard, sum(s.total_spend) over ( partition by s.nom_category order by s.date rows between unbounded preceding and current row ) as cumulative_spend, sum(coalesce(sl.sales,0)) over ( partition by s.nom_category order by s.date rows between unbounded preceding and current row ) as cumulative_sales from spends s left join sales_daily sl on sl.sale_date = s.date and sl.category_key = s.nom_category;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            